"""Write casefold_table.go: the characters whose str.casefold() differs from Go's
unicode.ToLower (simple lowercase). Run with the CPython the engine must match:

    python -I testdata/gen_casefold.py > casefold_table.go

Simple lowercase differs from Python's full lowercase only for U+0130; every other
difference comes from CaseFolding.txt (C and F entries). Unicode versions must agree
(CPython 3.12 and Go 1.24 both use Unicode 15.0.0); the differential test checks it.
"""
import sys
import unicodedata


def exceptions():
    for code in range(0x110000):
        if 0xD800 <= code <= 0xDFFF:
            continue
        char = chr(code)
        folded, lower = char.casefold(), char.lower()
        if folded != lower or len(lower) != 1:
            yield code, folded


def main():
    singles, multiples = [], []
    for code, folded in exceptions():
        (singles if len(folded) == 1 else multiples).append((code, folded))
    ranges = []
    for code, folded in singles:
        delta = ord(folded) - code
        if ranges and ranges[-1][1] == code - 1 and ranges[-1][2] == delta:
            ranges[-1][1] = code
        else:
            ranges.append([code, code, delta])
    out = sys.stdout
    out.write("// Code generated by testdata/gen_casefold.py from CPython "
              f"{sys.version.split()[0]} (Unicode {unicodedata.unidata_version}). DO NOT EDIT.\n\n")
    out.write("package pycompat\n\n")
    out.write("// foldRanges map lo..hi to the character plus delta.\n")
    out.write("var foldRanges = []foldRange{\n")
    for lo, hi, delta in ranges:
        out.write(f"\t{{0x{lo:04X}, 0x{hi:04X}, {delta}}},\n")
    out.write("}\n\n// foldExpansions are full case foldings to several characters.\n")
    out.write("var foldExpansions = map[rune]string{\n")
    for code, folded in multiples:
        text = "".join(f"\\u{ord(c):04X}" if ord(c) > 0x7F else c for c in folded)
        out.write(f"\t0x{code:04X}: \"{text}\",\n")
    out.write("}\n")


if __name__ == "__main__":
    main()
